-- Migration: Question generation — AUD batch 21 (30 questions)
-- Date: 2026-02-23
-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Management bias through misstatement patterns
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bridgewater Electronics, the engagement team notes that all six uncorrected misstatements identified during fieldwork increase reported net income. Under AU-C 450, the auditor should evaluate this pattern because it may indicate:', '["Management bias in the preparation of financial statements", "A material weakness in internal control over financial reporting", "An illegal act requiring disclosure in the audit report", "A scope limitation requiring a qualified opinion"]'::jsonb, 0, 'AU-C 450.11 requires the auditor to consider whether uncorrected misstatements may indicate management bias in the preparation of financial statements. When all identified misstatements consistently favor increased income, this directional pattern suggests potential bias rather than random error. In contrast, a material weakness (B) relates to control design or operation deficiencies, not misstatement direction.', 'medium', 3),

-- Q2: hard / L4 — Prior-year unremediated material weakness persisting
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Dynamics received a material weakness communication from the prior-year audit regarding revenue recognition controls. During the current-year audit, the engagement team confirms the same control deficiency persists, but no misstatements have been detected in the current period. The auditor should:', '["Remove the material weakness classification since no misstatements were identified this year", "Communicate the deficiency as a significant deficiency since it has been partially mitigated by the absence of errors", "Communicate the material weakness again because the control deficiency still has the potential for material misstatement", "Defer communication until management completes its planned remediation"]'::jsonb, 2, 'Under AU-C 265.A15, the severity of a control deficiency depends on the potential for misstatement rather than whether a misstatement actually occurred. A material weakness persists as long as the deficiency could reasonably result in a material misstatement, regardless of current-period results. However, removing the classification (A) incorrectly equates the absence of detected misstatements with effective controls.', 'hard', 4),

-- Q3: easy / L1 — Clearly trivial threshold definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does "clearly trivial" mean when applied to misstatements identified during an audit?', '["The misstatement is below the overall materiality threshold", "The misstatement affects only disclosures, not financial statement amounts", "The misstatement was caused by an unintentional error rather than fraud", "The misstatement is inconsequential both individually and in the aggregate"]'::jsonb, 3, 'AU-C 450.A2 defines "clearly trivial" as matters that are inconsequential whether taken individually or in the aggregate, and whether judged by size, nature, or circumstances. This threshold is set well below materiality. Unlike being below overall materiality (A), clearly trivial requires the amount to be so small that accumulation with other misstatements could not be material.', 'easy', 1),

-- Q4: easy / L1 — Control deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what is a deficiency in internal control?', '["Any finding the auditor identifies during tests of controls that requires management response", "A gap between the design of the control system and industry best practices", "A condition where a control does not exist or does not allow timely prevention or detection of misstatements", "A condition where a control operates exactly as designed but is insufficient to prevent all errors"]'::jsonb, 2, 'AU-C 265.07 defines a deficiency in internal control as existing when a control is designed, implemented, or operated such that it is unable to prevent, or detect and correct, misstatements on a timely basis, or when a necessary control is missing. In contrast, a gap relative to industry best practices (B) is not the standard''s definition of a control deficiency.', 'easy', 1),

-- Q5: easy / L2 — Factual misstatement classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeshore Retail, the auditor discovers that a $3,200 purchase was recorded twice in accounts payable due to a data entry error. This type of misstatement is best classified as:', '["A projected misstatement", "A judgmental misstatement", "An estimated misstatement", "A factual misstatement"]'::jsonb, 3, 'AU-C 450.A3 identifies factual misstatements as those about which there is no doubt—errors that have been specifically identified with certainty. A duplicate data entry is a clear, known error involving no estimation or judgment. Unlike a projected misstatement (A), which arises from extrapolating sample results to a population, a factual misstatement is directly observed.', 'easy', 2),

-- Q6: medium / L3 — Rollover approach to evaluate cumulative misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Software, the auditor identifies a $40,000 overstatement of prepaid expenses originating in 2024 that was not corrected. In 2025, the balance sheet remains overstated by $40,000 with no incremental income statement effect. Using the rollover approach, the auditor would treat the current-year misstatement as:', '["Zero, because no new misstatement originated in the current year''s income statement", "$40,000, because the balance sheet remains overstated by that amount", "$40,000, because the original error must be included each year until corrected", "$20,000, representing a prorated allocation of the original misstatement"]'::jsonb, 0, 'AU-C 450.A18 describes the rollover approach as evaluating misstatements based on amounts originating in the current period. Since the $40,000 overstatement originated entirely in 2024 with no incremental effect on 2025 income, the rollover approach treats the current-year amount as zero. In contrast, the iron curtain approach (B) would consider the full cumulative $40,000 balance sheet effect.', 'medium', 3),

-- Q7: medium / L3 — Segregation of duties deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Creek Distribution, the engagement team discovers that the accounts payable clerk can both create new vendor records and approve payments without a secondary review. Under AU-C 265, the auditor should evaluate this finding by assessing:', '["Whether any actual misstatements resulted from the lack of segregation during the audit period", "Whether the magnitude of transactions processed through this control creates a reasonable possibility of material misstatement", "Whether management has documented its acceptance of the risk in the entity''s risk assessment", "Whether the accounts payable clerk has a history of honest employment with the entity"]'::jsonb, 1, 'AU-C 265.A7 requires the auditor to evaluate a control deficiency''s severity based on the magnitude of potential misstatement and the likelihood it could result in material misstatement. The focus is on what could go wrong rather than on whether actual errors occurred during the period (A). A segregation of duties weakness is evaluated by the volume and dollar amount of transactions the control affects.', 'medium', 3),

-- Q8: hard / L3 — IT general control deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'While auditing Quartz Financial Group, the engagement team discovers that the IT department has no formal process for reviewing user access rights to the general ledger system. Twelve employees have unrestricted edit access, though only three require it for their job functions. The auditor should evaluate this IT general control deficiency by:', '["Considering the number and financial significance of accounts and transactions accessible to unauthorized users", "Reporting it only if an unauthorized user actually modified a general ledger entry during the period", "Classifying it as a significant deficiency solely because IT controls are presumed pervasive", "Deferring evaluation until the entity completes its own access review"]'::jsonb, 0, 'Under AU-C 265.A8, the auditor evaluates IT control deficiencies by considering the nature and financial significance of the data the deficiency could affect. Unrestricted general ledger access by nine unnecessary users creates the potential for unauthorized journal entries across all accounts. However, waiting for actual misstatements to occur (B) ignores that severity is assessed based on potential misstatement.', 'hard', 3),

-- Q9: medium / L3 — Recurring significant deficiency communication
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Manufacturing, the auditor identified a significant deficiency in inventory controls and communicated it to governance in the prior year. Management took no corrective action, and the same deficiency persists in the current year. Under AU-C 265, the auditor should:', '["Omit the deficiency from the current communication since it was reported in the prior year", "Communicate the significant deficiency again in writing to those charged with governance", "Escalate the deficiency to a material weakness solely because management failed to remediate it", "Communicate the deficiency only to management since governance was already informed"]'::jsonb, 1, 'AU-C 265.A19 states that the auditor should communicate significant deficiencies and material weaknesses each year they exist, even if previously communicated. There is no provision allowing omission of recurring deficiencies. Although failure to remediate may indicate governance issues (C), the deficiency is not automatically escalated to a material weakness without re-evaluating its potential for material misstatement.', 'medium', 3),

-- Q10: hard / L4 — Systematic misstatements across subsidiaries
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Aerospace, the engagement team identifies immaterial misstatements in three separate subsidiaries, each involving incorrect revenue cutoff at period end. Individually, each misstatement is below the subsidiary-level and consolidated materiality thresholds. The engagement partner should evaluate whether these misstatements:', '["Can be dismissed because each is individually immaterial at all levels", "Must be reported as a material weakness because they involve revenue", "Indicate a systematic failure in revenue recognition controls warranting a reassessment of the audit approach", "Require restatement of each subsidiary''s financial statements before consolidation"]'::jsonb, 2, 'Under AU-C 450.11, the auditor considers the nature and circumstances of misstatements, not just their individual magnitude. A consistent pattern of revenue cutoff errors across subsidiaries suggests a systematic control failure, even when each is individually immaterial. However, dismissing them (A) ignores the qualitative significance of recurring, directionally similar errors that may signal pervasive control issues.', 'hard', 4),

-- Q11: hard / L4 — Timely interim communication of deficiencies
(1, 'Misstatements and Control Deficiencies', 'While performing interim procedures for Riverstone Energy in September, the engagement team identifies what appears to be a material weakness in the cash disbursement authorization process. Year-end fieldwork is scheduled for February. The engagement partner should:', '["Wait until year-end fieldwork is complete to confirm the deficiency before communicating it", "Communicate the deficiency to those charged with governance on a timely basis, without waiting for year-end", "Issue a qualified opinion immediately based on the interim finding", "Communicate the finding only to management and defer governance communication to the final letter"]'::jsonb, 1, 'AU-C 265.12 requires the auditor to communicate significant deficiencies and material weaknesses to those charged with governance on a timely basis. However, waiting until year-end (A) would deprive governance of the opportunity to take corrective action during the remaining audit period. Timely communication serves the entity''s interest in prompt remediation regardless of whether year-end fieldwork has been completed.', 'hard', 4),

-- Q12: medium / L2 — Known vs projected misstatement distinction
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Medical Supplies, the engagement team selects a sample of 60 purchase orders and identifies a $4,500 pricing error in one order. The team then extrapolates the error rate to the full population of 3,000 purchase orders. The $4,500 identified in the sample is classified as a:', '["Known misstatement", "Projected misstatement", "Likely aggregate misstatement", "Possible misstatement"]'::jsonb, 0, 'AU-C 450.A3 distinguishes between known misstatements—specific errors actually identified in the sample—and projected misstatements, which result from extrapolating sample findings to the population. The $4,500 is a specifically identified error, making it a known misstatement. In contrast, the extrapolated total for the full population of 3,000 purchase orders (B) would be the projected misstatement.', 'medium', 2),

-- Q13: hard / L4 — Service organization control deficiency
(1, 'Misstatements and Control Deficiencies', 'The auditor of Summit Wealth Management discovers that a key service organization processes all client portfolio valuations but has no SOC 1 report available. Summit relies entirely on the service organization''s data without performing independent verification. The auditor should evaluate this situation as:', '["Acceptable if the service organization has a strong market reputation", "Irrelevant to Summit''s internal control evaluation since the deficiency exists at the service organization", "A potential control deficiency at Summit because management has not implemented controls over service organization activities", "A scope limitation that automatically requires a disclaimer of opinion"]'::jsonb, 2, 'Under AU-C 402.09 and AU-C 265, the user entity is responsible for establishing controls over service organization activities, including monitoring or independent verification of outputs. Unlike the view that the deficiency is irrelevant (B), the absence of both a SOC 1 report and compensating controls at Summit represents a deficiency in Summit''s own internal controls over outsourced functions.', 'hard', 4),

-- Q14: medium / L3 — Qualitative materiality for related party disclosures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cypress Lane Hotels, the auditor identifies an uncorrected $12,000 misstatement in a related party disclosure. The amount is well below the $500,000 materiality threshold. Under AU-C 450, the auditor should:', '["Require correction only if the misstatement exceeds performance materiality", "Exclude disclosure misstatements from the summary of uncorrected misstatements", "Treat the misstatement as clearly trivial because it is far below materiality", "Consider whether the misstatement is qualitatively material because it involves a related party transaction"]'::jsonb, 3, 'AU-C 450.11 requires the auditor to consider both quantitative and qualitative factors when evaluating misstatements. Related party disclosures are sensitive areas where even numerically small misstatements may be qualitatively material to users'' decision-making. In contrast, treating the misstatement as clearly trivial (C) ignores the heightened qualitative significance that related party information carries.', 'medium', 3),

-- Q15: medium / L3 — Corrected misstatements and audit strategy implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Ridge Construction, the engagement team identifies 15 misstatements in the first two months of fieldwork. Management promptly corrects all of them. Under AU-C 450, the auditor should:', '["Consider the corrected misstatements concluded because management has addressed them", "Evaluate the implications of the corrected misstatements on the overall audit strategy and risk assessment", "Reduce the scope of remaining procedures since management demonstrated effective error detection", "Exclude corrected misstatements from the engagement documentation"]'::jsonb, 1, 'AU-C 450.07 requires the auditor to consider the implications of identified misstatements on the audit, even after they are corrected by management. A high volume of misstatements may indicate additional errors exist, warranting increased testing or reassessment of risk. However, considering the matter closed (A) ignores the diagnostic value of corrected misstatements as indicators of potential process weaknesses.', 'medium', 3),

-- Q16: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'In audit sampling, what is a tolerable misstatement?', '["The maximum misstatement the auditor can accept and still conclude the sample supports the population balance", "The total of all misstatements found in the sample during testing", "The amount of misstatement that management agrees is acceptable", "The difference between the recorded balance and the audited balance"]'::jsonb, 0, 'AU-C 530.05 defines tolerable misstatement as a monetary amount set by the auditor such that the auditor obtains an appropriate level of assurance that the actual misstatement in the population does not exceed that amount. It is an auditor-determined threshold rather than a management-agreed amount (C), and relates to the entire population, not just sample findings (B).', 'easy', 1),

-- Q17: medium / L2 — Significant deficiency vs material weakness threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Logistics, the engagement team identifies a deficiency in the bank reconciliation process that could allow misstatements up to $75,000 to go undetected. Materiality is set at $200,000. Under AU-C 265, this deficiency is most likely classified as:', '["A material weakness because it involves a financial institution process", "An other deficiency that requires only management notification", "Not reportable because the potential misstatement is below materiality", "A significant deficiency because the potential misstatement is below materiality but important enough to merit governance attention"]'::jsonb, 3, 'AU-C 265.A12 indicates that a significant deficiency is less severe than a material weakness yet important enough to merit the attention of those charged with governance. Since the $75,000 potential misstatement is well below the $200,000 materiality but still substantial, it represents a significant deficiency. In contrast, a material weakness (A) requires a reasonable possibility that a material misstatement would not be prevented or detected.', 'medium', 2),

-- Q18: hard / L4 — Governance disputes deficiency classification
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Heritage Capital Partners, the engagement partner communicates a material weakness in the investment valuation process. The audit committee disagrees, arguing that no misstatements were found and the deficiency should be reclassified as a significant deficiency. The engagement partner should:', '["Reclassify the deficiency as a significant deficiency to maintain the client relationship", "Accept the audit committee''s assessment since they have more knowledge of the entity''s operations", "Maintain the material weakness classification if the auditor''s professional judgment supports it, regardless of governance''s disagreement", "Withdraw from the engagement because of the disagreement"]'::jsonb, 2, 'Under AU-C 265.13, the auditor''s evaluation of control deficiency severity is a matter of professional judgment not subject to override by management or governance. The classification is based on the potential for misstatement rather than actual occurrences. However, reclassifying to preserve the client relationship (A) would compromise auditor independence and professional judgment.', 'hard', 4),

-- Q19: medium / L2 — Documentation requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Falcon Transport Services, the engagement team identifies eight misstatements. Management corrects five and leaves three uncorrected. Under AU-C 450, the auditor''s documentation should include:', '["Only the three uncorrected misstatements, since the corrected ones no longer affect the financial statements", "Only the corrected misstatements, since they demonstrate the effectiveness of the audit", "All eight misstatements accumulated during the audit, the basis for the materiality evaluation, and management''s written representations", "A summary of the three uncorrected misstatements without any assessment of materiality"]'::jsonb, 2, 'AU-C 450.14 requires the auditor to document all misstatements accumulated during the audit, including both corrected and uncorrected items, the basis for evaluating whether uncorrected misstatements are material, and management''s written representations. In contrast, documenting only uncorrected misstatements (A) would omit the important diagnostic significance of corrected errors.', 'medium', 2),

-- Q20: easy / L1 — Written representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what written representation must the auditor obtain from management regarding uncorrected misstatements?', '["That management believes the uncorrected misstatements are immaterial individually and in the aggregate", "That management will correct all identified misstatements before issuing the financial statements", "That management acknowledges fault for all misstatements identified during the audit", "That management has hired additional staff to prevent future misstatements"]'::jsonb, 0, 'AU-C 450.13 requires the auditor to obtain a written representation from management that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. The representation concerns management''s materiality assessment rather than a commitment to correct the items (B) or an acknowledgment of fault (C).', 'easy', 1),

-- Q21: medium / L2 — Communication of other (non-significant) deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Pharmaceuticals, the engagement team identifies several control deficiencies that individually and in combination are less severe than a significant deficiency. Under AU-C 265, the auditor should communicate these other deficiencies:', '["In writing to those charged with governance, along with significant deficiencies", "Only if management specifically requests an assessment of all internal controls", "In the audit report as an other-matter paragraph", "To management, either in writing or orally, depending on the auditor''s professional judgment"]'::jsonb, 3, 'AU-C 265.11 states that the auditor should communicate to management deficiencies identified during the audit that merit management''s attention, even when below the significant deficiency threshold. These may be communicated orally or in writing. In contrast, written governance communication (A) is required only for significant deficiencies and material weaknesses, not lesser deficiencies.', 'medium', 2),

-- Q22: medium / L2 — Intentional misstatement and fraud risk implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Hill Investments, the engagement team discovers that a revenue transaction was intentionally recorded in the wrong period to meet quarterly targets. Under auditing standards, the auditor should treat this misstatement differently from an unintentional error because:', '["Intentional misstatements are always material regardless of amount", "Intentional misstatements cannot be aggregated with unintentional errors", "Intentional misstatements may indicate fraud risk factors that require reassessment of the audit approach", "Intentional misstatements must be reported to law enforcement before being communicated to governance"]'::jsonb, 2, 'Under AU-C 240.35 and AU-C 450.A20, an intentional misstatement raises concerns about management integrity and potential fraud, requiring the auditor to reconsider the risk assessment and overall audit strategy. Although intentional misstatements are significant, they are not automatically material regardless of amount (A)—their primary significance lies in the fraud risk indicators they reveal.', 'medium', 2),

-- Q23: medium / L2 — Timing deadline for written communication
(1, 'Misstatements and Control Deficiencies', 'The auditor of Ironworks Manufacturing completed fieldwork on March 15 and identified two significant deficiencies and one material weakness. Under AU-C 265, written communication of these findings to those charged with governance must occur:', '["Within 30 days after the audit report date", "Before issuing the audit report", "No later than 60 days following the report release date", "Within 90 days after the fiscal year end"]'::jsonb, 2, 'AU-C 265.12 requires the auditor to communicate significant deficiencies and material weaknesses in writing to those charged with governance on a timely basis, but no later than 60 days following the report release date. Although earlier communication is preferred, the standard does not require it before the audit report is issued (B), unlike what some practitioners assume.', 'medium', 2),

-- Q24: medium / L2 — Pervasive control deficiency impact on substantive procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Dynamics LLC, the auditor discovers that the entity has no formal financial closing process, resulting in numerous unreconciled accounts. The auditor determines this represents a material weakness. Under auditing standards, the auditor should also consider whether this deficiency:', '["Automatically requires a disclaimer of opinion", "Affects the nature, timing, and extent of substantive procedures needed to respond to the assessed risks", "Eliminates the need to test other controls in the financial close cycle", "Must be disclosed in the notes to the financial statements"]'::jsonb, 1, 'Under AU-C 265 and AU-C 330.07, identifying a material weakness in the financial close process requires the auditor to reconsider the audit approach, particularly the nature, timing, and extent of substantive procedures. However, a material weakness does not automatically trigger a disclaimer of opinion (A) but rather signals that greater substantive testing may be needed to obtain sufficient appropriate evidence.', 'medium', 2),

-- Q25: easy / L1 — Purpose of summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the auditor''s summary of uncorrected misstatements provided to management?', '["To document the auditor''s recommendation for adjusting entries", "To serve as evidence that the auditor performed sufficient testing", "To replace the management representation letter regarding financial statements", "To allow management to evaluate whether uncorrected misstatements are material to the financial statements"]'::jsonb, 3, 'AU-C 450.08 requires the auditor to communicate all uncorrected misstatements to management so that management can evaluate whether the financial statements are materially misstated. The summary enables informed decisions about whether to record corrections. Unlike a list of recommended entries (A), the summary''s primary purpose is to support management''s own materiality assessment.', 'easy', 1),

-- Q26: easy / L1 — Recipients of written deficiency communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom must the auditor communicate identified material weaknesses in writing?', '["Only to the entity''s external legal counsel", "To those charged with governance", "To the Securities and Exchange Commission", "To the entity''s shareholders at the annual meeting"]'::jsonb, 1, 'AU-C 265.09 requires the auditor to communicate in writing to those charged with governance all significant deficiencies and material weaknesses identified during the audit. This communication is directed to governance bodies such as the audit committee or board of directors, rather than to external regulators (C), shareholders (D), or legal counsel (A).', 'easy', 1),

-- Q27: easy / L1 — Design vs operating effectiveness
(1, 'Misstatements and Control Deficiencies', 'What are the two aspects of internal control evaluated when assessing a control deficiency?', '["Design effectiveness and operating effectiveness", "Cost efficiency and risk tolerance", "Management intent and employee competence", "Preventive strength and detective coverage"]'::jsonb, 0, 'AU-C 265.07 indicates that a control deficiency exists when a control is not properly designed or does not operate effectively to prevent, or detect and correct, misstatements on a timely basis. Design effectiveness addresses whether the control is suitably structured, whereas operating effectiveness addresses whether it functions consistently as intended. Cost efficiency (B) is not a factor in deficiency evaluation.', 'easy', 1),

-- Q28: easy / L1 — Reasonable possibility threshold
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what probability threshold distinguishes a material weakness from a significant deficiency?', '["A remote likelihood of material misstatement", "A reasonable possibility that a material misstatement will not be prevented or detected", "A certainty that the financial statements contain a material misstatement", "A probable likelihood of financial statement fraud"]'::jsonb, 1, 'AU-C 265.A11 defines a material weakness as a deficiency, or combination of deficiencies, where there is a reasonable possibility that a material misstatement will not be prevented, or detected and corrected, on a timely basis. "Reasonable possibility" is a lower threshold than "probable," whereas "remote" (A) represents a much lower likelihood that would not trigger classification as a material weakness.', 'easy', 1),

-- Q29: medium / L3 — Aggregating misstatements across line items
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Analytics, the engagement team identifies three uncorrected misstatements: a $35,000 overstatement of revenue, a $28,000 understatement of cost of goods sold, and a $22,000 overstatement of accounts receivable. Materiality is $100,000. When evaluating the aggregate effect, the auditor should:', '["Sum only the income statement misstatements because balance sheet misstatements have a separate materiality", "Evaluate each misstatement independently against materiality and ignore the aggregate effect", "Evaluate all three misstatements together because they cumulatively overstate both income and net assets", "Offset the revenue overstatement against the cost understatement to arrive at a net misstatement"]'::jsonb, 2, 'AU-C 450.10 requires the auditor to evaluate the aggregate of uncorrected misstatements and their effect on the financial statements as a whole. The revenue overstatement ($35,000) and cost of goods sold understatement ($28,000) both inflate income, while the receivable overstatement inflates net assets. Rather than offsetting them (D), the auditor should evaluate their combined effect on the financial statements.', 'medium', 3),

-- Q30: medium / L2 — Iron curtain vs rollover approach distinction
(1, 'Misstatements and Control Deficiencies', 'When evaluating the effect of prior-period uncorrected misstatements on the current-period financial statements, the iron curtain approach measures misstatements based on:', '["The total cumulative amount by which the current-period balance sheet is misstated", "The amount of new misstatements originating in only the current period", "The percentage of misstatements relative to total assets", "The number of periods the misstatement has remained uncorrected"]'::jsonb, 0, 'AU-C 450.A18 describes the iron curtain approach as quantifying a misstatement based on the effects of correcting all misstatements existing in the current-period balance sheet, regardless of when they originated. In contrast, the rollover approach (B) focuses only on the amount of misstatement originating in the current period. The iron curtain approach is generally more conservative for balance sheet evaluation.', 'medium', 2)
;

COMMIT;
